const gates=['Research','Story bank','Mock rounds','Evidence file','Questions for them','Logistics','Recovery plan'];
function run(i){return gates.slice(0,i).map((g,n)=>({gate:n+1,name:g,done:n<i}));}
console.log(JSON.stringify({system:'Signature Interview Protocol',gates_passed:run(4).filter(g=>g.done).length,of:gates.length}));

const dossier={claims:['led 4 engineers','cut costs 18%'],evidence:{'led 4 engineers':'perf reviews','cut costs 18%':'finance email'}};
function verify(){return dossier.claims.map(c=>({claim:c,backed:!!dossier.evidence[c]}));}
console.log(JSON.stringify({system:'Archive-Aware Candidate Dossier',verified:verify()}));

let stories=0;const target=12;
function add(){stories++;return {stories,target,pct:Math.round(stories/target*100)};}
console.log(JSON.stringify({system:'Million-March Preparation Counter',after_three:[add(),add(),add()][2]}));

const resume=['led team','python expert'];
const truth={ 'led team':true,'python expert':false };
console.log(JSON.stringify({system:'Drift-Check Your Resume',flags:resume.filter(c=>!truth[c]).map(c=>({claim:c,verdict:'remove or reword'}))}));

const crypto=require('crypto');
function seal(claim){return crypto.createHash('sha256').update(claim).digest('hex').slice(0,10);}
console.log(JSON.stringify({system:'Provenance of Claims',sealed:seal('cut load time 40%'),rule:'every number has a source'}));

const bank=['tell me about yourself','a time you failed','why this job'];
function mock(seed){return bank[seed%bank.length];}
console.log(JSON.stringify({system:'Assistant-Maker Mock Interviewer',round:[0,1,2].map(s=>mock(s*5+1))}));

const LADDER=['simple','compounded','complex'];
function proof(skill,level){return {skill,level,rung:LADDER[Math.min(level,2)],demo:'show, not tell'};}
console.log(JSON.stringify({system:'Teach-Ladder Skill Proof',proofs:[proof('debugging',0),proof('system design',2)]}));
